    "sourceUrl": "https://www.camara.leg.br",
    "articleUrl": "https://www.camara.leg.br/noticias/1322044-comissao-aprova-mudanca-em-regra-sobre-operacoes-de-comercio-exterior",
    "publishedAt": "23/11/2026 às 19:14",
    "category": "Congresso",
