    "ingestedAt": "23/11/2026 às 17:54",
    "imageUrl": "https://imagens.ebc.com.br/NSOF1sn9_DDjNkNPl7igFreIh4o=/1170x700/smart/https://agenciabrasil.ebc.com.br/sites/default/files/thumbnails/image/2026/09/15/55530389414_9c5deca160_o.jpg?itok=Ks5z0Qf9",
    "imageCaption": "AGU defende dispensa de liminar de Dino sobre escala 5x2",
